"use client";
import { useState } from "react";
import { Button } from "@fabrials/ui";
import { cn } from "@/lib/utils";
export function safeUrl(value: unknown): string | undefined {
  if (typeof value !== "string") return;
  try {
    const url = new URL(value);
    return ["https:", "http:"].includes(url.protocol) ? url.href : undefined;
  } catch {
    return;
  }
}
function Json({ value }: { value: unknown }) {
  return (
    <pre className="max-h-96 overflow-auto whitespace-pre-wrap break-words rounded-lg bg-muted/70 p-4 font-mono text-xs leading-relaxed">
      {JSON.stringify(value, null, 2) ?? String(value)}
    </pre>
  );
}
function Content({ value }: { value: unknown }) {
  if (!value || typeof value !== "object") return <Json value={value} />;
  const block = value as Record<string, unknown>;
  if (block.type === "text" && typeof block.text === "string")
    return (
      <p className="whitespace-pre-wrap break-words text-sm leading-relaxed">
        {block.text}
      </p>
    );
  if (block.type === "resource_link" && safeUrl(block.uri))
    return (
      <a
        className="text-sm underline underline-offset-4"
        href={safeUrl(block.uri)}
        target="_blank"
        rel="noopener noreferrer"
      >
        {String(block.name ?? block.uri)}
      </a>
    );
  if (
    block.type === "resource" &&
    block.resource &&
    typeof block.resource === "object"
  ) {
    const resource = block.resource as Record<string, unknown>;
    return typeof resource.text === "string" ? (
      <pre className="max-h-80 overflow-auto whitespace-pre-wrap text-xs">
        {resource.text}
      </pre>
    ) : (
      <Json value={resource} />
    );
  }
  if (
    typeof block.data === "string" &&
    block.data.length <= 8_000_000 &&
    typeof block.mimeType === "string"
  ) {
    const src = `data:${block.mimeType};base64,${block.data}`;
    // Only inert raster formats are embedded; remote URLs and SVG are never executed.
    if (
      block.type === "image" &&
      /^image\/(png|jpeg|webp|gif)$/.test(block.mimeType)
    )
      return (
        <picture>
          <img
            src={src}
            alt="Tool result"
            className="max-h-80 max-w-full rounded-md object-contain"
          />
        </picture>
      );
    if (
      block.type === "audio" &&
      /^audio\/(mpeg|mp3|wav|ogg|webm)$/.test(block.mimeType)
    )
      return <audio controls src={src} aria-label="Tool audio result" />;
  }
  return <Json value={value} />;
}
export function ResultView({
  result,
  className,
}: {
  result: unknown;
  className?: string;
}) {
  const [raw, setRaw] = useState(false);
  const object =
    result && typeof result === "object"
      ? (result as Record<string, unknown>)
      : undefined;
  const content = Array.isArray(object?.content)
    ? object.content
    : Array.isArray(object?.contents)
      ? object.contents
      : null;
  return (
    <div className={cn("space-y-3", className)}>
      <div className="flex items-center justify-between">
        <span className="text-xs font-medium text-muted-foreground">
          Result
        </span>
        <Button
          variant="ghost"
          size="xs"
          onClick={() => setRaw(!raw)}
          aria-pressed={raw}
        >
          {raw ? "Preview" : "Raw JSON"}
        </Button>
      </div>
      {raw ? (
        <Json value={result} />
      ) : (
        <>
          {content?.map((block, index) => (
            <Content key={index} value={block} />
          ))}
          {object && "structuredContent" in object ? (
            <Json value={object.structuredContent} />
          ) : (
            !content && <Json value={result} />
          )}
        </>
      )}
    </div>
  );
}

export type JsonSchema =
  | boolean
  | {
      [key: string]: unknown;
      type?: string | string[];
      properties?: Record<string, JsonSchema>;
      required?: string[];
      enum?: unknown[];
      description?: string;
      title?: string;
      items?: JsonSchema;
    };
export interface ToolDefinition {
  name: string;
  title?: string;
  description?: string;
  inputSchema: JsonSchema;
  annotations?: {
    readOnlyHint?: boolean;
    destructiveHint?: boolean;
    untrustedContentHint?: boolean;
    consequentialHint?: boolean;
    [key: string]: unknown;
  };
}
export interface Execution {
  id: string;
  name: string;
  source: "human" | "agent" | "simulator";
  status: "running" | "success" | "error" | "cancelled";
  startedAt: number;
  completedAt?: number;
  args: Record<string, unknown>;
  result?: unknown;
  error?: string;
  progress?: { progress: number; total?: number; message?: string };
}
export type Support = "checking" | "native" | "legacy" | "unsupported";
export interface ToolContext {
  signal: AbortSignal;
  source: Execution["source"];
}
export interface WebTool extends ToolDefinition {
  execute: (
    args: Record<string, unknown>,
    context: ToolContext,
  ) => unknown | Promise<unknown>;
}
export function errorMessage(error: unknown) {
  return error instanceof Error ? error.message : "The operation failed.";
}

"use client";
import { Check, Circle, Loader2, X } from "lucide-react";
import { Badge, Button, Progress } from "@fabrials/ui";
import { ResultView } from "@/components/webmcp/result-view";
import type { Execution } from "@/lib/mcp/types";
const statusLabels: Record<string, string> = {
  running: "Running",
  success: "Done",
  error: "Failed",
  cancelled: "Cancelled",
};
const defaultSourceLabels: Record<Execution["source"], string> = {
  human: "You",
  agent: "Agent",
  simulator: "Simulator",
};
export function ExecutionLog({
  executions,
  onCancel,
  onClear,
  sourceLabels = defaultSourceLabels,
}: {
  executions: Execution[];
  onCancel?: (id: string) => void;
  onClear?: () => void;
  /** Who made each call, in the reader's words. */
  sourceLabels?: Partial<Record<Execution["source"], string>>;
}) {
  return (
    <section className="space-y-3" aria-label="Execution history">
      <header className="flex items-center justify-between">
        <h3 className="text-sm font-medium">
          Activity{" "}
          <span className="ml-1 text-muted-foreground">
            {executions.length}
          </span>
        </h3>
        {onClear && (
          <Button variant="ghost" size="xs" onClick={onClear}>
            Clear history
          </Button>
        )}
      </header>
      {!executions.length && (
        <div className="flex min-h-28 flex-col items-center justify-center gap-2 rounded-md border border-dashed text-muted-foreground">
          <Circle className="size-4" />
          <p className="text-xs">Run a tool to see its activity here.</p>
        </div>
      )}
      {executions.map((e) => (
        <details
          key={e.id}
          className="rounded-md border p-3"
          open={e.status === "running" || undefined}
        >
          <summary className="flex cursor-pointer list-none flex-wrap items-center gap-2 text-xs">
            {e.status === "running" ? (
              <Loader2 className="size-3.5 animate-spin motion-reduce:animate-none" />
            ) : e.status === "success" ? (
              <Check className="size-3.5 text-[var(--fui-success-ink)]" />
            ) : (
              <X className="size-3.5 text-destructive" />
            )}
            <span className="flex-1 font-mono">{e.name}</span>
            <Badge variant="outline">{sourceLabels[e.source] ?? defaultSourceLabels[e.source]}</Badge>
            <span role="status" className="text-muted-foreground">
              {statusLabels[e.status] ?? e.status}
            </span>
          </summary>
          <div className="mt-4 space-y-3">
            {e.progress && (
              <>
                <Progress
                  max={100}
                  value={
                    e.progress.total
                      ? (e.progress.progress / e.progress.total) * 100
                      : undefined
                  }
                />
                <p role="status" className="text-xs text-muted-foreground">
                  {e.progress.message ?? `${e.progress.progress} completed`}
                </p>
              </>
            )}
            {e.status === "running" && onCancel && (
              <Button
                size="xs"
                variant="outline"
                onClick={() => onCancel(e.id)}
              >
                Cancel request
              </Button>
            )}
            {e.status === "cancelled" && (
              <p className="text-xs text-muted-foreground">
                Request cancelled. Remote effects may have already occurred.
              </p>
            )}
            {e.error && e.status !== "cancelled" && (
              <p role="alert" className="text-xs text-destructive">
                {e.error}
              </p>
            )}
            {e.result !== undefined && <ResultView result={e.result} />}
            <details className="text-xs">
              <summary className="cursor-pointer text-muted-foreground">
                Arguments
              </summary>
              <pre className="mt-2 overflow-auto">
                {JSON.stringify(e.args, null, 2)}
              </pre>
            </details>
          </div>
        </details>
      ))}
    </section>
  );
}
